$ErrorActionPreference = "Stop"
$ExpectedHead = "a6f9b5e"
$Repo = (Get-Location).Path

if ((git branch --show-current) -ne "main") { throw "Run this script from the main branch." }
$Head = (git rev-parse --short HEAD).Trim()
if ($Head -ne $ExpectedHead) { throw "Expected HEAD $ExpectedHead but found $Head. Pull/inspect before applying this batch." }
if (-not (Test-Path ".\mvnw.cmd")) { throw "Maven wrapper not found. Run from the LYAPUNOV repository root." }
git diff --quiet; if ($LASTEXITCODE -ne 0) { throw "Tracked working-tree changes exist." }
git diff --cached --quiet; if ($LASTEXITCODE -ne 0) { throw "Staged changes exist." }

$Payloads = @{}
$Payloads["src/main/java/com/lyapunov/repository/WorkerHeartbeatStore.java"] = ""
$Payloads["src/main/java/com/lyapunov/repository/WorkerHeartbeatRepository.java"] = ""
$Payloads["src/main/java/com/lyapunov/worker/OutboxRelayWorker.java"] = ""
$Payloads["src/test/java/com/lyapunov/worker/OutboxRelayWorkerTest.java"] = ""
$Payloads["docs/AUTOMATIC_WORKER_HEARTBEATS.md"] = ""

foreach ($RelativePath in $Payloads.Keys) {
    $FullPath = Join-Path $Repo $RelativePath
    $Parent = Split-Path $FullPath -Parent
    New-Item -ItemType Directory -Force -Path $Parent | Out-Null
    $Bytes = [Convert]::FromBase64String($Payloads[$RelativePath])
    [System.IO.File]::WriteAllBytes($FullPath, $Bytes)
    Write-Host "Wrote $RelativePath"
}

Write-Host "`nRunning full Maven verification..." -ForegroundColor Cyan
& .\mvnw.cmd -B -ntp clean verify
if ($LASTEXITCODE -ne 0) { throw "Maven verification failed with exit code $LASTEXITCODE. No files were staged or committed." }

$Paths = @(
    "src/main/java/com/lyapunov/repository/WorkerHeartbeatStore.java",
    "src/main/java/com/lyapunov/repository/WorkerHeartbeatRepository.java",
    "src/main/java/com/lyapunov/worker/OutboxRelayWorker.java",
    "src/test/java/com/lyapunov/worker/OutboxRelayWorkerTest.java",
    "docs/AUTOMATIC_WORKER_HEARTBEATS.md"
)
git add -- $Paths
if ($LASTEXITCODE -ne 0) { throw "git add failed." }
git diff --cached --check
if ($LASTEXITCODE -ne 0) { throw "Staged diff check failed." }
git commit -m "feat: integrate automatic worker heartbeat reporting"
if ($LASTEXITCODE -ne 0) { throw "git commit failed. Review staged changes; nothing was pushed." }
git push origin main
if ($LASTEXITCODE -ne 0) { throw "git push failed. The local commit exists; resolve push issue and push main." }

Write-Host "`nBATCH 08 COMPLETE: verified, committed, and pushed." -ForegroundColor Green
git log -1 --oneline
git status -sb
